import { readFile } from 'node:fs/promises';
import path from 'node:path';

const sources = [
  'extension/src/i18nMessages.js',
  'extension/src/i18n.js',
  'extension/src/aiProviders.js',
  'extension/src/attachmentSupport.js',
  'extension/src/correctionSchema.js',
  'extension/src/savedInstructions.js',
  'extension/src/filePreview.js',
  'src/content/moodleContent.js',
];

export async function buildContentBundle(root) {
  const parts = await Promise.all(sources.map(async source =>
    `// Source: ${source}\n${source === 'src/content/moodleContent.js' ? 'return ' : ''}${(await readFile(path.join(root, source), 'utf8')).replaceAll('\r\n', '\n')}`));
  return `// Generated by scripts/build-content.mjs. Edit src/content/moodleContent.js and the source modules.\n` +
    `(() => {\n` +
    `const pageUrl = new URL(location.href);\n` +
    `if (pageUrl.protocol !== 'https:' || !pageUrl.pathname.endsWith('/mod/assign/view.php') || pageUrl.searchParams.get('action') !== 'grader') return;\n` +
    `if (document.getElementById('mca-side-panel-host')) return;\n` +
    parts.join('\n;\n') + '\n})();\n';
}
